'use strict';
(async()=>{
 const $=id=>document.getElementById(id);
 const response=await fetch('assets/art-manifest.json');if(!response.ok)throw Error('Не удалось загрузить каталог');
 const data=await response.json();let emotion=0;
 const option=(value,text)=>{const e=document.createElement('option');e.value=value;e.textContent=text;return e};
 const position=i=>`${(i%3)*50}% ${Math.floor(i/3)*50}%`;
 const sprite=(el,file,cell)=>{el.style.backgroundImage=`url("${file}")`;el.style.backgroundPosition=cell==null?'center':position(cell);el.style.backgroundSize=cell==null?'cover':'300% 300%'};
 const character=()=>data.characters.find(c=>c.id===$('character').value);
 const variant=()=>character().variants.find(v=>v.id===$('costume').value);
 const costumeLabels={travel:'Дорожное пальто',coat:'Пальто',cardigan:'Кардиган',scarf:'Клетчатый шарф',linen:'Повседневный',blouse:'Блузка',shirt:'Рубашка',suit:'Костюм',blazer:'Жакет',flight:'Рабочий комбинезон',uniform:'Форма',headset:'Гарнитура',evening:'Вечернее платье',eva:'Скафандр',future:'Запись из будущего'};
 function renderPortrait(){const c=character(),v=variant(),e=data.emotions[emotion];sprite($('portrait'),v.file,emotion);$('portrait').style.aspectRatio=`${v.width} / ${v.height}`;$('portrait').setAttribute('aria-label',`${c.name}: ${e.label}`);$('character-name').textContent=c.name;$('character-role').textContent=c.role;$('emotion-name').textContent=e.label;$('sheet-link').href=v.file;document.querySelectorAll('.emotion').forEach((b,i)=>{b.setAttribute('aria-pressed',String(i===emotion));sprite(b.querySelector('.mini'),v.file,i);b.querySelector('.mini').style.aspectRatio=`${v.width} / ${v.height}`});const img=new Image();img.onerror=()=>{$('status').textContent='Этот ресурс пока недоступен.'};img.onload=()=>{$('status').textContent=''};img.src=v.file;}
 function renderCharacter(){const c=character();$('costume').replaceChildren(...c.variants.map(v=>option(v.id,costumeLabels[v.id]||v.id)));renderPortrait()}
 function renderBackground(){const b=data.backgrounds.find(x=>x.id===$('background').value);sprite($('backdrop'),b.file,b.cell);$('backdrop').style.setProperty('--background-ratio',`${b.width} / ${b.height}`)}
 function renderStory(){const s=Number($('story').value);$('character').replaceChildren(...data.characters.filter(c=>c.story===s).map(c=>option(c.id,c.name)));renderCharacter();const backgrounds=data.backgrounds.filter(b=>b.story===s);$('background').replaceChildren(...backgrounds.map(b=>option(b.id,b.name)));renderBackground();$('locations').replaceChildren(...backgrounds.map(b=>{const btn=document.createElement('button');btn.type='button';btn.className='location';const img=document.createElement('span');img.className='image';sprite(img,b.file,b.cell);img.style.aspectRatio=`${b.width} / ${b.height}`;const label=document.createElement('span');label.className='label';label.textContent=b.name;btn.append(img,label);btn.onclick=()=>{$('background').value=b.id;renderBackground();$('stage').scrollIntoView({block:'center'})};return btn}));$('scenes').replaceChildren(...data.scenes.filter(x=>x.story===s).map(sc=>{const li=document.createElement('li');li.append(document.createTextNode(sc.title));const small=document.createElement('small');small.textContent=sc.characters.map(id=>data.characters.find(c=>c.id===id).name).join(' · ')+' / '+sc.emotions.map(id=>data.emotions.find(e=>e.id===id).label).join(', ');li.append(small);return li}));}
 $('story').replaceChildren(...data.stories.map((s,i)=>option(i,s)));
 $('emotions').replaceChildren(...data.emotions.map((e,i)=>{const b=document.createElement('button');b.type='button';b.className='emotion';const mini=document.createElement('span');mini.className='mini';const label=document.createElement('span');label.className='label';label.textContent=e.label;b.append(mini,label);b.onclick=()=>{emotion=i;renderPortrait()};return b}));
 $('story').onchange=renderStory;$('character').onchange=renderCharacter;$('costume').onchange=renderPortrait;$('background').onchange=renderBackground;renderStory();
})().catch(e=>{document.getElementById('status').textContent=e.message});
